`timescale 1ns/1ps
// I-10 (I9-D2, Kalash 2026-11-05): K-3 re-provisioned to config 16 / IMEM 64 bytes in the P7 subsystem (I-9 list,
// pq_noc_subsystem_p7 #(.K3_IMEM_LEN(7'd64)), PQ_MAC_ON). Expected responses: vectors/d2_k3_64.svh, generated by
// scripts/d2_golden.py from the pinned teammate reference (TILE_KEY_BYTES = 32) and cross-checked with hashlib SHA3-256.
// Measurement claim under test: "the first 64 bytes of IMEM at MEAS_BASE" (with the 16-byte config and the tile id).
// Response layout (97 bytes, little-endian): tile [0+:56], epoch [56+:80], nonce [136+:128], measurement [264+:256], tag [520+:256].
// Checks (CHECKS = 12, frozen before the first run):
//   D2_TXN<r>_RESPONSE   endpoint_response == teammate expected response, r = 0, 1, 2                                  3
//   D2_TXN<r>_GRANT      the verifier grants (authorized[3]) with the approved 64-byte measurement, r = 0, 1, 2         3
//   D2_TXN0_DATA         authorized write committed and read back after the row-0 grant                                1
//   D2_BYTE16_BOUND      row 1 with IMEM byte 16 flipped (first byte outside the old 16-byte window): a fresh response
//                        (nonce of row 1) whose measurement differs from the DUT's own row-1 measurement; no grant,
//                        tile 3 not authorized                                                                         1
//   D2_TAIL_BYTE_BOUND   the same for IMEM byte 63 (last byte of the 64-byte window)                                   1
//   D2_IMEM16_REFUSED    row 0 requested with imem_len = 16 (old profile): K-3 refuses it in the endpoint
//                        (endpoint_rejected +1, one k3_fault pulse), no grant, tile 3 not authorized                             1
//   D2_REGRANT           row 0 again: grant with the expected response                                                 1
//   D2_NO_UNAUTH_COMMIT  every memory commit decided with authorized[3] = 1, at least one commit                       1
// Bounded waits feed checks; TB_TIMEOUT only for the global limit.
module tb_i10_d2;
  import noc_pkg::*;
  logic clk = 0, rst = 1, start_attestation = 0, revoke = 0, trusted_clear = 0;
  always #10 clk = ~clk;
  logic [79:0] boot_epoch, attest_epoch;
  logic [127:0] nonce;
  logic [255:0] root_secret, approved_measurement;
  logic [111:0] context_in;
  logic [3:0] context_len;
  logic [511:0] config_data, imem;
  logic [6:0] config_len, imem_len;
  logic [5:0] app_valid, app_payload_valid, app_ready, app_payload_ready, app_tx_error;
  coord_t [5:0] app_destination;
  msg_type_e [5:0] app_message;
  logic [5:0][10:0] app_control;
  logic [5:0][31:0] app_payload;
  logic spoof_raw_valid = 0, spoof_raw_ready;
  flit_t spoof_raw_flit;
  logic [5:0] authorized;
  logic rot_busy, grant_done, attestation_failed;
  logic [775:0] endpoint_response, expected_response;
  logic [31:0] memory_commits, memory_last_data, endpoint_rejected, verifier_rejected, q_forwarded;
  logic [511:0] keys_p7;
  // L2 directed demo keys (tiles 3 <-> 4) from the full-chain vectors; the D2 rows only change the attestation inputs.
  `include "full_chain.svh"
  assign keys_p7 = {KEYS[(3*6+4)*256 +: 256], KEYS[(4*6+3)*256 +: 256]};
  pq_noc_subsystem_p7 #(.TB_INJECT(1'b1), .VERIFIER_TIMEOUT(20000), .K3_IMEM_LEN(7'd64)) dut(.clk, .rst, .start_attestation,
    .revoke, .trusted_clear, .boot_epoch, .attest_epoch, .nonce, .root_secret,
    .approved_measurement, .directed_keys(keys_p7), .context_in, .context_len, .config_data, .imem, .config_len, .imem_len,
    .app_valid, .app_payload_valid, .app_ready, .app_payload_ready, .app_destination, .app_message, .app_control, .app_payload,
    .spoof_raw_valid, .spoof_raw_flit, .spoof_raw_ready, .authorized, .rot_busy, .grant_done, .attestation_failed,
    .endpoint_response, .memory_commits, .memory_last_data, .q_forwarded, .app_tx_error, .endpoint_rejected, .verifier_rejected,
    .mem_rdata(32'd0));
  `include "d2_k3_64.svh"
  localparam logic [31:0] ADDR = 32'h2200_0100;
  int checks = 0, errors = 0;
  task automatic check(input bit ok, input string name);
    checks++;
    if (ok) $display("[PASS] %s", name); else begin errors++; $display("[FAIL] %s", name); end
  endtask
  int grants = 0, fails = 0, n_commit = 0, bad_commit = 0, rd_n = 0, k3n = 0;
  bit rd_open = 0;
  logic [31:0] rd_data = 0, commits_q = 0;
  logic auth3_q = 0;
  always @(posedge clk) begin
    if (!rst) begin
      if (grant_done) grants++;
      if (attestation_failed) fails++;
      if (dut.endpoint.k3_fault) k3n++;   // one-cycle pulse per K-3 refusal
      if (dut.rhv[3] && dut.rxmsg[3] == MSG_MEM_RD_RESP) rd_open = 1;
      else if (rd_open && dut.rpv[3]) begin rd_data = dut.rxdata[3]; rd_n++; rd_open = 0; end
      if (memory_commits != commits_q) begin n_commit++; if (!auth3_q) bad_commit++; end
      commits_q = memory_commits; auth3_q = authorized[3];
    end else begin commits_q = 0; auth3_q = 0; end
  end
  task automatic do_reset();
    @(negedge clk); rst = 1; app_valid = 0; app_payload_valid = 0; revoke = 0; start_attestation = 0;
    repeat (6) @(negedge clk); rst = 0; repeat (5) @(negedge clk);
  endtask
  task automatic pulse_start(); @(negedge clk); start_attestation = 1; @(negedge clk); start_attestation = 0; endtask
  task automatic wait_idle(); automatic int n = 0; while ((rot_busy || dut.verifier.vs != 0) && n < 60000) begin @(negedge clk); n++; end endtask
  task automatic attest(input int row, output bit ok, output bit resp_ok);
    automatic int g0 = grants, n = 0;
    load_d2(row); pulse_start();
    while (!(grants == g0 + 1 && authorized[3]) && n < 60000) begin @(negedge clk); n++; end
    ok = grants == g0 + 1 && authorized[3]; resp_ok = endpoint_response == expected_response;
    wait_idle(); repeat (20) @(negedge clk);
  endtask
  // one attestation expected to fail; returns the fresh response and whether anything was granted
  task automatic attest_fail(output logic [775:0] r, output bit granted);
    automatic int g0 = grants;
    pulse_start(); wait_idle(); repeat (50) @(negedge clk);
    r = endpoint_response; granted = grants != g0;
  endtask
  task automatic app_hdr(input msg_type_e m, input logic [10:0] c, input int limit, output bit ok);
    automatic int n = 0;
    @(negedge clk); app_destination[3] = tile_to_coord(TILE_MEMORY); app_message[3] = m; app_control[3] = c; app_valid[3] = 1;
    do begin @(posedge clk); n++; end while (!app_ready[3] && n < limit);
    ok = app_ready[3]; @(negedge clk); app_valid[3] = 0;
  endtask
  task automatic app_words(input logic [31:0] w0, input logic [31:0] w1, input int nw, output bit ok);
    ok = 1;
    for (int i = 0; i < nw && ok; i++) begin
      automatic int n = 0;
      repeat (3) @(negedge clk);
      app_payload[3] = i == 0 ? w0 : w1; app_payload_valid[3] = 1;
      do begin @(posedge clk); n++; end while (!app_payload_ready[3] && n < 2000);
      ok = app_payload_ready[3]; @(negedge clk); app_payload_valid[3] = 0;
    end
  endtask
  task automatic write_read(input logic [31:0] d, output bit ok);
    automatic bit h, w, h2, w2; automatic int c0 = memory_commits, r0 = rd_n;
    app_hdr(MSG_MEM_WR_REQ, 11'h780, 2000, h); w = 0; if (h) app_words(ADDR, d, 2, w);
    repeat (400) @(negedge clk);
    app_hdr(MSG_MEM_RD_REQ, 11'h000, 2000, h2); w2 = 0; if (h2) app_words(ADDR, 0, 1, w2);
    repeat (400) @(negedge clk);
    ok = h && w && h2 && w2 && memory_commits == c0 + 1 && memory_last_data == d && rd_n == r0 + 1 && rd_data == d;
  endtask
  task automatic do_revoke();
    automatic int n = 0;
    @(negedge clk); revoke = 1; @(negedge clk); revoke = 0;
    while (authorized[3] && n < 1500) begin @(negedge clk); n++; end
    wait_idle(); repeat (20) @(negedge clk);
  endtask
  // flip one IMEM byte of row 1 and check that it is measured (DUT-vs-DUT, fresh response by nonce)
  task automatic byte_bound(input int b, input logic [775:0] ref1, input string name);
    automatic bit ok0, rok0, granted; automatic logic [775:0] r;
    attest(0, ok0, rok0);                          // a response with a different nonce precedes: a stale value is caught
    load_d2(1); imem[b*8] = ~imem[b*8];
    attest_fail(r, granted);
    check(ok0 && r[136 +: 128] == ref1[136 +: 128] && r[264 +: 256] != ref1[264 +: 256] && !granted && !authorized[3],
      $sformatf("%s fresh=%0b meas_differs=%0b granted=%0b authorized3=%b", name, r[136 +: 128] == ref1[136 +: 128],
                r[264 +: 256] != ref1[264 +: 256], granted, authorized[3]));
  endtask

  initial begin
    bit ok, rok, dok; logic [775:0] resp [3];
    $display("CONFIG: TOP=tb_i10_d2 CHECKS=12 K3_CONFIG_LEN=16 K3_IMEM_LEN=64 VECTORS=d2_k3_64");
    app_valid = 0; app_payload_valid = 0; app_destination = '0; app_message = '0; app_control = 0; app_payload = 0; spoof_raw_flit = '0;
    load_d2(0); boot_epoch = BOOT;
    do_reset();
    for (int r = 0; r < 3; r++) begin
      attest(r, ok, rok); resp[r] = endpoint_response;
      check(rok, $sformatf("D2_TXN%0d_RESPONSE match=%0b imem_len=%0d", r, rok, imem_len));
      check(ok, $sformatf("D2_TXN%0d_GRANT granted=%0b", r, ok));
      if (r == 0) begin
        write_read(32'hD200_0000, dok);
        check(dok, $sformatf("D2_TXN0_DATA ok=%0b data=%h read=%h", dok, memory_last_data, rd_data));
      end
      do_revoke();
    end
    byte_bound(16, resp[1], "D2_BYTE16_BOUND");
    byte_bound(63, resp[1], "D2_TAIL_BYTE_BOUND");
    begin
      automatic bit ok0, rok0, granted; automatic logic [775:0] r; automatic logic [31:0] rj0; automatic int k30;
      attest(0, ok0, rok0);
      rj0 = endpoint_rejected; k30 = k3n;
      load_d2(0); imem_len = 7'd16;
      attest_fail(r, granted);
      check(ok0 && endpoint_rejected == rj0 + 1 && k3n == k30 + 1 && !granted && !authorized[3],
        $sformatf("D2_IMEM16_REFUSED rejected=+%0d k3_pulses=+%0d granted=%0b authorized3=%b", endpoint_rejected - rj0,
                  k3n - k30, granted, authorized[3]));
    end
    repeat (300) @(negedge clk);
    attest(0, ok, rok);
    check(ok && rok, $sformatf("D2_REGRANT granted=%0b response=%0b", ok, rok));
    check(bad_commit == 0 && n_commit >= 1, $sformatf("D2_NO_UNAUTH_COMMIT commits=%0d bad=%0d", n_commit, bad_commit));
    $display("CHECKS : %0d", checks);
    $display("ERRORS : %0d", errors);
    $display("RESULT : %s", errors == 0 && checks == 12 ? "PASS" : "FAIL");
    $finish;
  end
  initial begin #60ms; $display("TB_TIMEOUT global"); $finish; end
endmodule
